      &lt;InputData&gt;{&quot;Value&quot;:&quot;\u003cdiv class=\&quot;chart-card kpi-card\&quot;\u003e\n  \u003ch2\u003eIndicator de Activitate Totală \u003c/h2\u003e\n  \u003cdiv class=\&quot;kpi-value\&quot; id=\&quot;totalActivityValue\&quot;\u003e0\u003c/div\u003e\n\u003c/div\u003e\n\n\u003cscript\u003e\n  const totalRaw = [eventsNumber]; // now just a number\n\n  // Validate value\n  const total = (typeof totalRaw === \u0027number\u0027 \u0026\u0026 !isNaN(totalRaw)) ? totalRaw : 0;\n\n  const element = document.getElementById(\u0027totalActivityValue\u0027);\n\n  function animateValue(el, end, duration = 1200) {\n    let start = 0;\n    const startTime = performance.now();\n\n    function update(currentTime) {\n      const elapsed = currentTime - startTime;\n      const progress = Math.min(elapsed / duration, 1);\n\n      const eased = 1 - Math.pow(1 - progress, 3);\n\n      const currentValue = Math.floor(eased * end);\n\n      el.textContent = currentValue.toLocaleString(\u0027ro-RO\u0027);\n\n      if (progress \u003c 1) {\n        requestAnimationFrame(update);\n      } else {\n        el.textContent = end.toLocaleString(\u0027ro-RO\u0027);\n      }\n    }\n\n    requestAnimationFrame(update);\n  }\n\n  animateValue(element, total);\n\u003c/script\u003e&quot;,&quot;Align&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;SaveToReport&quot;:false}&lt;/InputData&gt;
      &lt;Align&gt;
        &lt;Expression /&gt;
        &lt;Value&gt;left&lt;/Value&gt;
        &lt;IsExpression&gt;False&lt;/IsExpression&gt;
        &lt;Parameters&gt;System.Collections.Generic.Dictionary`2[System.String,System.Object]&lt;/Parameters&gt;
      &lt;/Align&gt;
      &lt;SaveToReport&gt;False&lt;/SaveToReport&gt;
      &lt;Value&gt;&lt;![CDATA[&lt;div class=&quot;chart-card kpi-card&quot;&gt;
  &lt;h2&gt;Indicator de Activitate Totală &lt;/h2&gt;
  &lt;div class=&quot;kpi-value&quot; id=&quot;totalActivityValue&quot;&gt;0&lt;/div&gt;
&lt;/div&gt;

&lt;script&gt;
  const totalRaw = [eventsNumber]; // now just a number

  // Validate value
  const total = (typeof totalRaw === &#39;number&#39; &amp;&amp; !isNaN(totalRaw)) ? totalRaw : 0;

  const element = document.getElementById(&#39;totalActivityValue&#39;);

  function animateValue(el, end, duration = 1200) {
    let start = 0;
    const startTime = performance.now();

    function update(currentTime) {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      const eased = 1 - Math.pow(1 - progress, 3);

      const currentValue = Math.floor(eased * end);

      el.textContent = currentValue.toLocaleString(&#39;ro-RO&#39;);

      if (progress &lt; 1) {
        requestAnimationFrame(update);
      } else {
        el.textContent = end.toLocaleString(&#39;ro-RO&#39;);
      }
    }

    requestAnimationFrame(update);
  }

  animateValue(element, total);
&lt;/script&gt;]]&gt;&lt;/Value&gt;
