      &lt;InputData&gt;{&quot;Value&quot;:&quot;\u003cdiv class=\&quot;chart-card\&quot;\u003e\n  \u003ch2\u003eDistribuția Accesărilor (Top 5 Instituții)\u003c/h2\u003e\n  \u003cdiv class=\&quot;chart-container\&quot;\u003e\n    \u003ccanvas id=\&quot;institutionsChart\&quot;\u003e\u003c/canvas\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n\n\u003cscript\u003e\n  const apiResponse = [JSONAggrTop5Inst];\n\n  // Safe extraction with optional chaining and fallback empty array\n  const buckets = apiResponse?.data?.buckets || [];\n  const top5 = buckets.slice(0, 5);\n\n  const chartLabels = top5.map(item =\u003e item.key);\n  const chartData = top5.map(item =\u003e item.doc_count);\n\n  const ctx = document.getElementById(\u0027institutionsChart\u0027).getContext(\u00272d\u0027);\n  \n  new Chart(ctx, {\n    type: \u0027bar\u0027,\n    data: {\n      labels: chartLabels,\n      datasets: [{\n        label: \u0027Număr Accesări\u0027,\n        data: chartData,\n        backgroundColor: [\n          \u0027rgba(54, 162, 235, 0.75)\u0027,\n          \u0027rgba(75, 192, 192, 0.75)\u0027,\n          \u0027rgba(255, 206, 86, 0.75)\u0027,\n          \u0027rgba(153, 102, 255, 0.75)\u0027,\n          \u0027rgba(255, 159, 64, 0.75)\u0027\n        ],\n        borderColor: [\n          \u0027rgba(54, 162, 235, 1)\u0027,\n          \u0027rgba(75, 192, 192, 1)\u0027,\n          \u0027rgba(255, 206, 86, 1)\u0027,\n          \u0027rgba(153, 102, 255, 1)\u0027,\n          \u0027rgba(255, 159, 64, 1)\u0027\n        ],\n        borderWidth: 1.5,\n        borderRadius: 6\n      }]\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: {\n          display: false\n        },\n        tooltip: {\n          callbacks: {\n            label: function(context) {\n              return ` Accesări: ${context.raw}`;\n            }\n          }\n        }\n      },\n      scales: {\n        y: {\n          beginAtZero: true,\n          ticks: {\n            precision: 0\n          },\n          title: {\n            display: true,\n            text: \u0027Număr Accesări\u0027\n          }\n        },\n        x: {\n          title: {\n            display: true,\n            text: \u0027Instituții\u0027\n          }\n        }\n      }\n    }\n  });\n\u003c/script\u003e&quot;,&quot;Align&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;SaveToReport&quot;:false}&lt;/InputData&gt;
      &lt;Align&gt;
        &lt;Expression /&gt;
        &lt;Value&gt;left&lt;/Value&gt;
        &lt;IsExpression&gt;False&lt;/IsExpression&gt;
        &lt;Parameters&gt;System.Collections.Generic.Dictionary`2[System.String,System.Object]&lt;/Parameters&gt;
      &lt;/Align&gt;
      &lt;SaveToReport&gt;False&lt;/SaveToReport&gt;
      &lt;Value&gt;&lt;![CDATA[&lt;div class=&quot;chart-card&quot;&gt;
  &lt;h2&gt;Distribuția Accesărilor (Top 5 Instituții)&lt;/h2&gt;
  &lt;div class=&quot;chart-container&quot;&gt;
    &lt;canvas id=&quot;institutionsChart&quot;&gt;&lt;/canvas&gt;
  &lt;/div&gt;
&lt;/div&gt;

&lt;script&gt;
  const apiResponse = [JSONAggrTop5Inst];

  // Safe extraction with optional chaining and fallback empty array
  const buckets = apiResponse?.data?.buckets || [];
  const top5 = buckets.slice(0, 5);

  const chartLabels = top5.map(item =&gt; item.key);
  const chartData = top5.map(item =&gt; item.doc_count);

  const ctx = document.getElementById(&#39;institutionsChart&#39;).getContext(&#39;2d&#39;);
  
  new Chart(ctx, {
    type: &#39;bar&#39;,
    data: {
      labels: chartLabels,
      datasets: [{
        label: &#39;Număr Accesări&#39;,
        data: chartData,
        backgroundColor: [
          &#39;rgba(54, 162, 235, 0.75)&#39;,
          &#39;rgba(75, 192, 192, 0.75)&#39;,
          &#39;rgba(255, 206, 86, 0.75)&#39;,
          &#39;rgba(153, 102, 255, 0.75)&#39;,
          &#39;rgba(255, 159, 64, 0.75)&#39;
        ],
        borderColor: [
          &#39;rgba(54, 162, 235, 1)&#39;,
          &#39;rgba(75, 192, 192, 1)&#39;,
          &#39;rgba(255, 206, 86, 1)&#39;,
          &#39;rgba(153, 102, 255, 1)&#39;,
          &#39;rgba(255, 159, 64, 1)&#39;
        ],
        borderWidth: 1.5,
        borderRadius: 6
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          display: false
        },
        tooltip: {
          callbacks: {
            label: function(context) {
              return ` Accesări: ${context.raw}`;
            }
          }
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0
          },
          title: {
            display: true,
            text: &#39;Număr Accesări&#39;
          }
        },
        x: {
          title: {
            display: true,
            text: &#39;Instituții&#39;
          }
        }
      }
    }
  });
&lt;/script&gt;]]&gt;&lt;/Value&gt;
