      &lt;BindPreserveLayout&gt;&lt;![CDATA[False]]&gt;&lt;/BindPreserveLayout&gt;
      &lt;BindValue&gt;&lt;![CDATA[]]&gt;&lt;/BindValue&gt;
      &lt;BindOnChange&gt;&lt;![CDATA[]]&gt;&lt;/BindOnChange&gt;
      &lt;InputType&gt;static-text&lt;/InputType&gt;
      &lt;InputData&gt;{&quot;Value&quot;:&quot;\u003cdiv class=\&quot;chart-card\&quot;\u003e\n  \u003ch2\u003eDistribuție tipuri de accesări\u003c/h2\u003e\n  \u003cdiv class=\&quot;chart-container\&quot;\u003e\n    \u003ccanvas id=\&quot;actionTypePieChart\&quot;\u003e\u003c/canvas\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n\n\u003cscript\u003e\n  const apiResponse = [JSONAggrTipActiune];\n\n  const buckets = apiResponse?.data?.buckets || [];\n\n  const hasData = buckets.length \u003e 0 \u0026\u0026 buckets.some(item =\u003e item.doc_count \u003e 0);\n\n  let actionLabels, actionData, backgroundColors;\n\n  if (hasData) {\n    actionLabels = buckets.map(item =\u003e item.key);\n    actionData = buckets.map(item =\u003e item.doc_count);\n\n    const colorMap = {\n      \u0027Citire\u0027: \u0027#2ec4b6\u0027,\n      \u0027Actualizare\u0027: \u0027#ff9f1c\u0027,\n      \u0027Creare\u0027: \u0027#3a86ef\u0027,\n      \u0027Stergere\u0027: \u0027#e71d36\u0027\n    };\n    const fallbackPalette = [\u0027#2ec4b6\u0027, \u0027#ff9f1c\u0027, \u0027#3a86ef\u0027, \u0027#e71d36\u0027, \u0027#9966ff\u0027, \u0027#4bc0c0\u0027];\n\n    backgroundColors = actionLabels.map((label, index) =\u003e \n      colorMap[label] || fallbackPalette[index % fallbackPalette.length]\n    );\n  } else {\n    actionLabels = [\u0027Fără date\u0027];\n    actionData = [1];\n    backgroundColors = [\u0027#e0e0e0\u0027];\n  }\n\n  const totalCount = hasData ? actionData.reduce((sum, value) =\u003e sum + value, 0) : 0;\n\n  // 3. Render Chart\n  const actionCtx = document.getElementById(\u0027actionTypePieChart\u0027).getContext(\u00272d\u0027);\n\n  new Chart(actionCtx, {\n    type: \u0027pie\u0027,\n    data: {\n      labels: actionLabels,\n      datasets: [{\n        label: \u0027Tipologia Acțiunilor\u0027,\n        data: actionData,\n        backgroundColor: backgroundColors,\n        borderWidth: hasData ? 1 : 0,\n        hoverOffset: hasData ? 6 : 0\n      }]\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: {\n          position: \u0027bottom\u0027,\n          labels: {\n            boxWidth: 14,\n            padding: 15,\n            font: {\n              size: 13\n            }\n          }\n        },\n        tooltip: {\n          enabled: hasData, // Disable tooltips if there\u0027s no data\n          callbacks: {\n            label: function(context) {\n              const label = context.label || \u0027\u0027;\n              const value = context.raw || 0;\n              const percentage = totalCount \u003e 0 ? ((value / totalCount) * 100).toFixed(1) : 0;\n              return ` ${label}: ${value} accesări (${percentage}%)`;\n            }\n          }\n        }\n      }\n    }\n  });\n\u003c/script\u003e&quot;,&quot;Align&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;SaveToReport&quot;:false}&lt;/InputData&gt;
      &lt;Align&gt;
        &lt;Expression /&gt;
        &lt;Value&gt;left&lt;/Value&gt;
        &lt;IsExpression&gt;False&lt;/IsExpression&gt;
        &lt;Parameters&gt;System.Collections.Generic.Dictionary`2[System.String,System.Object]&lt;/Parameters&gt;
      &lt;/Align&gt;
      &lt;SaveToReport&gt;False&lt;/SaveToReport&gt;
      &lt;Value&gt;&lt;![CDATA[&lt;div class=&quot;chart-card&quot;&gt;
  &lt;h2&gt;Distribuție tipuri de accesări&lt;/h2&gt;
  &lt;div class=&quot;chart-container&quot;&gt;
    &lt;canvas id=&quot;actionTypePieChart&quot;&gt;&lt;/canvas&gt;
  &lt;/div&gt;
&lt;/div&gt;

&lt;script&gt;
  const apiResponse = [JSONAggrTipActiune];

  const buckets = apiResponse?.data?.buckets || [];

  const hasData = buckets.length &gt; 0 &amp;&amp; buckets.some(item =&gt; item.doc_count &gt; 0);

  let actionLabels, actionData, backgroundColors;

  if (hasData) {
    actionLabels = buckets.map(item =&gt; item.key);
    actionData = buckets.map(item =&gt; item.doc_count);

    const colorMap = {
      &#39;Citire&#39;: &#39;#2ec4b6&#39;,
      &#39;Actualizare&#39;: &#39;#ff9f1c&#39;,
      &#39;Creare&#39;: &#39;#3a86ef&#39;,
      &#39;Stergere&#39;: &#39;#e71d36&#39;
    };
    const fallbackPalette = [&#39;#2ec4b6&#39;, &#39;#ff9f1c&#39;, &#39;#3a86ef&#39;, &#39;#e71d36&#39;, &#39;#9966ff&#39;, &#39;#4bc0c0&#39;];

    backgroundColors = actionLabels.map((label, index) =&gt; 
      colorMap[label] || fallbackPalette[index % fallbackPalette.length]
    );
  } else {
    actionLabels = [&#39;Fără date&#39;];
    actionData = [1];
    backgroundColors = [&#39;#e0e0e0&#39;];
  }

  const totalCount = hasData ? actionData.reduce((sum, value) =&gt; sum + value, 0) : 0;

  // 3. Render Chart
  const actionCtx = document.getElementById(&#39;actionTypePieChart&#39;).getContext(&#39;2d&#39;);

  new Chart(actionCtx, {
    type: &#39;pie&#39;,
    data: {
      labels: actionLabels,
      datasets: [{
        label: &#39;Tipologia Acțiunilor&#39;,
        data: actionData,
        backgroundColor: backgroundColors,
        borderWidth: hasData ? 1 : 0,
        hoverOffset: hasData ? 6 : 0
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: &#39;bottom&#39;,
          labels: {
            boxWidth: 14,
            padding: 15,
            font: {
              size: 13
            }
          }
        },
        tooltip: {
          enabled: hasData, // Disable tooltips if there&#39;s no data
          callbacks: {
            label: function(context) {
              const label = context.label || &#39;&#39;;
              const value = context.raw || 0;
              const percentage = totalCount &gt; 0 ? ((value / totalCount) * 100).toFixed(1) : 0;
              return ` ${label}: ${value} accesări (${percentage}%)`;
            }
          }
        }
      }
    }
  });
&lt;/script&gt;]]&gt;&lt;/Value&gt;
