      &lt;Value&gt;&lt;![CDATA[&lt;div class=&quot;chart-card&quot;&gt;
  &lt;h2&gt;Categorii de Date Accesate&lt;/h2&gt;
  &lt;div class=&quot;chart-container&quot;&gt;
    &lt;canvas id=&quot;dataCategoryDonutChart&quot;&gt;&lt;/canvas&gt;
