&lt;/div&gt;

&lt;script&gt;
  const apiResponse = [JSONAggrCategoriiDate];
  const categoryList = [JSONCategorii];

  const buckets = apiResponse?.data?.buckets || [];

  // Build lookup: code -&gt; category
  const codeToCategory = {};
  categoryList.forEach(item =&gt; {
    codeToCategory[item.Cod] = item.Nume;
  });

  // Aggregate counts per category
  const categoryCounts = {};

  buckets.forEach(item =&gt; {
    const category = codeToCategory[item.key] || &#39;Altele&#39;;

    if (!categoryCounts[category]) {
      categoryCounts[category] = 0;
    }

    categoryCounts[category] += item.doc_count;
  });

  // Convert to sortable array
  let categoryEntries = Object.entries(categoryCounts);

  // Sort descending by value
  categoryEntries.sort((a, b) =&gt; b[1] - a[1]);

  const hasData = categoryEntries.length &gt; 0 &amp;&amp; categoryEntries.some(entry =&gt; entry[1] &gt; 0);

  const labels = hasData ? categoryEntries.map(entry =&gt; entry[0]) : [&#39;Fără date&#39;];
  const data = hasData ? categoryEntries.map(entry =&gt; entry[1]) : [1];

  const colorMap = {
    &#39;Date de identificare directa&#39;: &#39;#3a86ef&#39;,
    &#39;Date de contact&#39;: &#39;#2ec4b6&#39;,
    &#39;Date financiare&#39;: &#39;#ffbe0b&#39;,
    &#39;Date cu caracter special&#39;: &#39;#ff006e&#39;,
    &#39;Date demografice&#39;: &#39;#8338ec&#39;,
    &#39;Date profesionale&#39;: &#39;#fb5607&#39;,
    &#39;Date de identificare electronica&#39;: &#39;#4cc9f0&#39;,
    &#39;Date de asigurare si asistenta sociala&#39;: &#39;#90dbf4&#39;,
    &#39;Date biometrice simple&#39;: &#39;#c77dff&#39;,
    &#39;Altele&#39;: &#39;#8d99ae&#39;
  };

  const backgroundColors = hasData
    ? labels.map(label =&gt; colorMap[label] || &#39;#8d99ae&#39;)
    : [&#39;#e0e0e0&#39;];

  const total = hasData ? data.reduce((a, b) =&gt; a + b, 0) : 0;

  const ctx = document.getElementById(&#39;dataCategoryDonutChart&#39;).getContext(&#39;2d&#39;);

  new Chart(ctx, {
    type: &#39;doughnut&#39;,
    data: {
      labels: labels,
      datasets: [{
        data: data,
        backgroundColor: backgroundColors,
        borderWidth: hasData ? 1 : 0,
        hoverOffset: hasData ? 6 : 0
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: &#39;60%&#39;,
      plugins: {
        legend: {
          position: &#39;bottom&#39;,
          labels: {
            boxWidth: 14,
            padding: 15,
            font: {
              size: 13
            }
          }
        },
        tooltip: {
          enabled: hasData,
          callbacks: {
            label: function(context) {
              const label = context.label || &#39;&#39;;
              const value = context.raw || 0;
              const percentage = total &gt; 0 ? ((value / total) * 100).toFixed(1) : 0;
              return ` ${label}: ${value} (${percentage}%)`;
            }
          }
        }
      }
    }
  });
&lt;/script&gt;]]&gt;&lt;/Value&gt;
