      &lt;Value&gt;&lt;![CDATA[&lt;div class=&quot;chart-card&quot;&gt;
  &lt;h2&gt;Evoluția Accesărilor &#238;n Timp pe Instituții&lt;/h2&gt;
  &lt;div class=&quot;chart-container&quot;&gt;
    &lt;canvas id=&quot;institutionsTimeChart&quot;&gt;&lt;/canvas&gt;
  &lt;/div&gt;
&lt;/div&gt;

&lt;script&gt;
  const rawData = [dataArr] || [];

  // Step 1: Aggregate data → { month: { institution: count } }
  const aggregation = {};

  rawData.forEach(item =&gt; {
    const dateStr = item?.S14?.value;
    const institution = item?.S13?.value || &#39;Necunoscut&#39;;

    if (!dateStr) return;

    const date = new Date(dateStr);
    const monthKey = date.getFullYear() + &#39;-&#39; + String(date.getMonth() + 1).padStart(2, &#39;0&#39;);

    if (!aggregation[monthKey]) {
      aggregation[monthKey] = {};
    }

    if (!aggregation[monthKey][institution]) {
      aggregation[monthKey][institution] = 0;
    }

    aggregation[monthKey][institution]++;
  });

  // Step 2: Get sorted months
  const months = Object.keys(aggregation).sort();

  // Step 3: Get all institutions
  const institutionsSet = new Set();
  Object.values(aggregation).forEach(monthData =&gt; {
    Object.keys(monthData).forEach(inst =&gt; institutionsSet.add(inst));
  });

  const institutions = Array.from(institutionsSet);

  // Step 4: Build datasets
  const colors = [
    &#39;#3a86ef&#39;, &#39;#2ec4b6&#39;, &#39;#ffbe0b&#39;, &#39;#ff006e&#39;,
    &#39;#8338ec&#39;, &#39;#fb5607&#39;, &#39;#4cc9f0&#39;, &#39;#90dbf4&#39;
  ];

  const datasets = institutions.map((inst, index) =&gt; {
    const data = months.map(month =&gt; {
      return aggregation[month][inst] || 0;
    });

    return {
      label: inst,
      data: data,
      borderColor: colors[index % colors.length],
      backgroundColor: colors[index % colors.length],
      tension: 0.3,
      fill: false
    };
  });

  const hasData = months.length &gt; 0 &amp;&amp; datasets.some(ds =&gt; ds.data.some(v =&gt; v &gt; 0));

  const ctx = document.getElementById(&#39;institutionsTimeChart&#39;).getContext(&#39;2d&#39;);

  new Chart(ctx, {
    type: &#39;line&#39;,
    data: {
      labels: hasData ? months : [&#39;&#39;],
      datasets: hasData ? datasets : []
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: &#39;bottom&#39;
        },
        tooltip: {
          enabled: hasData
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0
          },
          title: {
            display: true,
            text: &#39;Număr accesări&#39;
          }
        },
        x: {
          title: {
            display: true,
            text: &#39;Lună&#39;
          }
        }
      }
    }
  });
&lt;/script&gt;]]&gt;&lt;/Value&gt;
