      &lt;BindShow&gt;&lt;![CDATA[]]&gt;&lt;/BindShow&gt;
      &lt;BindEnable&gt;&lt;![CDATA[]]&gt;&lt;/BindEnable&gt;
      &lt;BindPreserveLayout&gt;&lt;![CDATA[False]]&gt;&lt;/BindPreserveLayout&gt;
      &lt;BindValue&gt;&lt;![CDATA[]]&gt;&lt;/BindValue&gt;
      &lt;BindOnChange&gt;&lt;![CDATA[]]&gt;&lt;/BindOnChange&gt;
      &lt;InputType&gt;static-text&lt;/InputType&gt;
      &lt;InputData&gt;{&quot;Value&quot;:&quot;\u003cdiv class=\&quot;chart-card\&quot;\u003e\n  \u003ch2\u003eMatricea Acțiunilor pe Tip de Date\u003c/h2\u003e\n  \u003cdiv class=\&quot;chart-container\&quot;\u003e\n    \u003ccanvas id=\&quot;stackedActionsChart\&quot;\u003e\u003c/canvas\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n\n\u003cscript\u003e\n  const rawData = [dataArr] || [];\n\n  // Step 1: Aggregate → { dataType: { action: count } }\n  const aggregation = {};\n\n  rawData.forEach(item =\u003e {\n    const dataType = item?.S22?.value || \u0027Necunoscut\u0027;\n    const action = item?.S20?.value || \u0027Necunoscut\u0027;\n\n    if (!aggregation[dataType]) {\n      aggregation[dataType] = {};\n    }\n\n    if (!aggregation[dataType][action]) {\n      aggregation[dataType][action] = 0;\n    }\n\n    aggregation[dataType][action]++;\n  });\n\n  const dataTypes = Object.keys(aggregation);\n\n  // Step 2: Get all actions\n  const actionsSet = new Set();\n  Object.values(aggregation).forEach(obj =\u003e {\n    Object.keys(obj).forEach(action =\u003e actionsSet.add(action));\n  });\n\n  const actions = Array.from(actionsSet);\n\n  // Step 3: Build datasets (one per action)\n  const colorMap = {\n    \u0027Citire\u0027: \u0027#2ec4b6\u0027,\n    \u0027Actualizare\u0027: \u0027#ff9f1c\u0027,\n    \u0027Creare\u0027: \u0027#3a86ef\u0027,\n    \u0027Ștergere\u0027: \u0027#e71d36\u0027,\n    \u0027Stergere\u0027: \u0027#e71d36\u0027\n  };\n\n  const fallbackColors = [\u0027#3a86ef\u0027, \u0027#2ec4b6\u0027, \u0027#ffbe0b\u0027, \u0027#ff006e\u0027, \u0027#8338ec\u0027];\n\n  const datasets = actions.map((action, index) =\u003e {\n    const data = dataTypes.map(type =\u003e {\n      return aggregation[type][action] || 0;\n    });\n\n    return {\n      label: action,\n      data: data,\n      backgroundColor: colorMap[action] || fallbackColors[index % fallbackColors.length],\n      borderRadius: 4\n    };\n  });\n\n  const hasData = dataTypes.length \u003e 0 \u0026\u0026 datasets.some(ds =\u003e ds.data.some(v =\u003e v \u003e 0));\n\n  const ctx = document.getElementById(\u0027stackedActionsChart\u0027).getContext(\u00272d\u0027);\n\n  new Chart(ctx, {\n    type: \u0027bar\u0027,\n    data: {\n      labels: hasData ? dataTypes : [\u0027\u0027],\n      datasets: hasData ? datasets : []\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: {\n          position: \u0027bottom\u0027\n        },\n        tooltip: {\n          enabled: hasData\n        }\n      },\n      scales: {\n        x: {\n          stacked: true,\n          title: {\n            display: true,\n            text: \u0027Tipuri de date\u0027\n          }\n        },\n        y: {\n          stacked: true,\n          beginAtZero: true,\n          ticks: {\n            precision: 0\n          },\n          title: {\n            display: true,\n            text: \u0027Număr accesări\u0027\n          }\n        }\n      }\n    }\n  });\n\u003c/script\u003e&quot;,&quot;Align&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;SaveToReport&quot;:false}&lt;/InputData&gt;
      &lt;Align&gt;
        &lt;Expression /&gt;
        &lt;Value&gt;left&lt;/Value&gt;
        &lt;IsExpression&gt;False&lt;/IsExpression&gt;
