      &lt;InputType&gt;static-text&lt;/InputType&gt;
      &lt;InputData&gt;{&quot;Value&quot;:&quot;\u003cdiv class=\&quot;chart-card\&quot;\u003e\n  \u003ch2\u003eStatistica Notificărilor și Alertelor (zilnic)\u003c/h2\u003e\n  \u003cdiv class=\&quot;chart-container\&quot;\u003e\n    \u003ccanvas id=\&quot;notificationsComboChart\&quot;\u003e\u003c/canvas\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n\n\u003cscript\u003e\n  function ensureArray(data) {\n    if (!data) return [];\n    if (Array.isArray(data)) return data;\n\n    try {\n      const parsed = JSON.parse(data);\n      return Array.isArray(parsed) ? parsed : [];\n    } catch {\n      return [];\n    }\n  }\n\n  const events = ensureArray([dataArr]);\n  const notifications = ensureArray([NotificariJSON]);\n\n  // Index notificări\n  const notifMap = {};\n  notifications.forEach(n =\u003e {\n    if (n \u0026\u0026 n.LogId) {\n      notifMap[n.LogId] = n;\n    }\n  });\n\n  // Agregare pe zi\n  const aggregation = {};\n\n  events.forEach(event =\u003e {\n    const dateStr = event?.S14?.value;\n    const logId = event?.[\&quot;Log.id\&quot;]?.value;\n\n    if (!dateStr) return;\n\n    const date = new Date(dateStr);\n    const dayKey = date.toISOString().split(\u0027T\u0027)[0];\n\n    if (!aggregation[dayKey]) {\n      aggregation[dayKey] = {\n        events: 0,\n        email: 0,\n        app: 0\n      };\n    }\n\n    aggregation[dayKey].events++;\n\n    const notif = notifMap[logId];\n\n    if (notif) {\n      if (notif.StatusNotificareEmail) {\n        aggregation[dayKey].email++;\n      }\n\n      if (notif.StatusNotificareApp) {\n        aggregation[dayKey].app++;\n      }\n    }\n  });\n\n  const days = Object.keys(aggregation).sort();\n\n  const eventData = days.map(d =\u003e aggregation[d].events);\n  const emailData = days.map(d =\u003e aggregation[d].email);\n  const appData = days.map(d =\u003e aggregation[d].app);\n\n  const hasData = days.length \u003e 0 \u0026\u0026 eventData.some(v =\u003e v \u003e 0);\n\n  const ctx = document.getElementById(\u0027notificationsComboChart\u0027).getContext(\u00272d\u0027);\n\n  new Chart(ctx, {\n    data: {\n      labels: hasData \n        ? days.map(d =\u003e new Date(d).toLocaleDateString(\u0027ro-RO\u0027, { day: \u00272-digit\u0027, month: \u0027short\u0027 }))\n        : [\u0027\u0027],\n      datasets: hasData ? [\n        {\n          type: \u0027bar\u0027,\n          label: \u0027Accesări\u0027,\n          data: eventData,\n          backgroundColor: \u0027#3a86ef\u0027,\n          yAxisID: \u0027y\u0027\n        },\n        {\n          type: \u0027line\u0027,\n          label: \u0027Notificări Email\u0027,\n          data: emailData,\n          borderColor: \u0027#ff9f1c\u0027,\n          backgroundColor: \u0027#ff9f1c\u0027,\n          tension: 0.3,\n          pointRadius: 4,\n          pointHoverRadius: 6,\n          yAxisID: \u0027y1\u0027\n        },\n        {\n          type: \u0027line\u0027,\n          label: \u0027Notificări App\u0027,\n          data: appData,\n          borderColor: \u0027#2ec4b6\u0027,\n          backgroundColor: \u0027#2ec4b6\u0027,\n          tension: 0.3,\n          pointRadius: 4,\n          pointHoverRadius: 6,\n          yAxisID: \u0027y1\u0027\n        }\n      ] : []\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: {\n          position: \u0027bottom\u0027\n        },\n        tooltip: {\n          enabled: hasData\n        }\n      },\n      scales: {\n        x: {\n          title: {\n            display: true,\n            text: \u0027Zi\u0027\n          }\n        },\n        y: {\n          beginAtZero: true,\n          position: \u0027left\u0027,\n          title: {\n            display: true,\n            text: \u0027Număr accesări\u0027\n          }\n        },\n        y1: {\n          beginAtZero: true,\n          position: \u0027right\u0027,\n          grid: {\n            drawOnChartArea: false\n          },\n          title: {\n            display: true,\n            text: \u0027Notificări\u0027\n          }\n        }\n      }\n    }\n  });\n\u003c/script\u003e&quot;,&quot;Align&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;SaveToReport&quot;:false}&lt;/InputData&gt;
