              const index = elements[0].index;
    const month = months[index]; // YYYY-MM

    const [year, monthNum] = month.split(&#39;-&#39;).map(Number);

    const firstDate = new Date(year, monthNum - 1, 1, 0, 0, 0);
    const lastDate = new Date(year, monthNum, 0, 23, 59, 0);

    function formatDate(d) {
