atLabel) : [\u0027Fără date\u0027];\n\n  // ✅ date formatter yyyy-MM-dd HH:mm:ss\n  function formatDateTime(d) {\n    const pad = n =\u003e String(n).padStart(2, \u00270\u0027);\n    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;\n  }\n\n  const ctx = document.getElementById(\u0027timeSeriesChart\u0027).getContext(\u00272d\u0027);\n\n  new Chart(ctx, {\n    type: \u0027line\u0027,\n    data: {\n      labels: labels,\n      datasets: hasData ? [{\n        label: \u0027Număr accesări\u0027,\n        data: values,\n        borderColor: \u0027#3a86ef\u0027,\n        backgroundColor: \u0027rgba(58, 134, 239, 0.2)\u0027,\n        tension: 0.3,\n        fill: true,\n        pointRadius: 4,\n        pointHoverRadius: 6\n      }] : [{\n        label: \u0027Fără date\u0027,\n        data: [1],\n        backgroundColor: \u0027#e0e0e0\u0027,\n        borderColor: \u0027#e0e0e0\u0027\n      }]\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n\n      onClick: (evt, elements) =\u003e {\n        if (!elements.length) return;\n\n        // ✅ doar dacă suntem pe luni\n        if (agregare !== \u0027zile\u0027) {\n          const index = elements[0].index;\n          const selectedKey = keys[index]; // YYYY-MM\n\n          const [year, month] = selectedKey.split(\u0027-\u0027).map(Number);\n\n          // ✅ first \u0026 last day\n          const firstDay = new Date(year, month - 1, 1, 0, 0, 0);\n          const lastDay = new Date(year, month, 0, 23, 59, 59);\n\n          const firstFormatted = formatDateTime(firstDay);\n          const lastFormatted = formatDateTime(lastDay);\n\n          // ✅ update query params\n          dnnsf.updateQueryStringParam(\u0027graf10Agregare\u0027,\u0027zile\u0027);\n          dnnsf.updateQueryStringParam(\u0027graf10Start\u0027, firstFormatted);\n          dnnsf.updateQueryStringParam(\u0027graf10End\u0027, lastFormatted);\n