      &lt;Value&gt;&lt;![CDATA[&lt;div class=&quot;chart-card chart-card-full&quot;&gt;
  &lt;h2&gt;Evoluția accesărilor &#238;n timp&lt;/h2&gt;
  &lt;div class=&quot;chart-container&quot;&gt;
    &lt;canvas id=&quot;timeSeriesChart&quot;&gt;&lt;/canvas&gt;
  &lt;/div&gt;
&lt;/div&gt;

&lt;script&gt;
  function ensureArray(data) {
    if (!data) return [];
    if (Array.isArray(data)) return data;

    try {
      const parsed = JSON.parse(data);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  const events = ensureArray([Get:graf10dataArr=[dataArr]]);

  // ✅ agregare din query string
  const agregare = &#39;[QueryString:graf10Agregare]&#39; || &#39;luni&#39;;

  const aggregation = {};

  events.forEach(event =&gt; {
    const dateStr = event?.S14?.value;
    if (!dateStr) return;

    const date = new Date(dateStr);

    let key;

    if (agregare === &#39;zile&#39;) {
      key = date.toISOString().split(&#39;T&#39;)[0]; // YYYY-MM-DD
    } else {
      key = date.getFullYear() + &#39;-&#39; + String(date.getMonth() + 1).padStart(2, &#39;0&#39;); // YYYY-MM
    }

    aggregation[key] = (aggregation[key] || 0) + 1;
  });

  const keys = Object.keys(aggregation).sort();
  const values = keys.map(k =&gt; aggregation[k]);

  const hasData = keys.length &gt; 0 &amp;&amp; values.some(v =&gt; v &gt; 0);

  // ✅ Romanian labels
  function formatLabel(key) {
    if (agregare === &#39;zile&#39;) {
      const d = new Date(key);
      return d.toLocaleDateString(&#39;ro-RO&#39;, { day: &#39;2-digit&#39;, month: &#39;short&#39; });
    } else {
      const [year, month] = key.split(&#39;-&#39;);
      return new Date(year, month - 1).toLocaleDateString(&#39;ro-RO&#39;, { month: &#39;short&#39;, year: &#39;numeric&#39; });
    }
  }

  const labels = hasData ? keys.map(formatLabel) : [&#39;Fără date&#39;];

  // ✅ date formatter yyyy-MM-dd HH:mm:ss
  function formatDateTime(d) {
    const pad = n =&gt; String(n).padStart(2, &#39;0&#39;);
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  }

  const ctx = document.getElementById(&#39;timeSeriesChart&#39;).getContext(&#39;2d&#39;);

  new Chart(ctx, {
    type: &#39;line&#39;,
    data: {
      labels: labels,
      datasets: hasData ? [{
        label: &#39;Număr accesări&#39;,
        data: values,
        borderColor: &#39;#3a86ef&#39;,
        backgroundColor: &#39;rgba(58, 134, 239, 0.2)&#39;,
        tension: 0.3,
        fill: true,
        pointRadius: 4,
        pointHoverRadius: 6
      }] : [{
        label: &#39;Fără date&#39;,
        data: [1],
        backgroundColor: &#39;#e0e0e0&#39;,
        borderColor: &#39;#e0e0e0&#39;
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,

      onClick: (evt, elements) =&gt; {
        if (!elements.length) return;

        // ✅ doar dacă suntem pe luni
        if (agregare !== &#39;zile&#39;) {
          const index = elements[0].index;
          const selectedKey = keys[index]; // YYYY-MM

          const [year, month] = selectedKey.split(&#39;-&#39;).map(Number);

          // ✅ first &amp; last day
          const firstDay = new Date(year, month - 1, 1, 0, 0, 0);
          const lastDay = new Date(year, month, 0, 23, 59, 59);

          const firstFormatted = formatDateTime(firstDay);
          const lastFormatted = formatDateTime(lastDay);

          // ✅ update query params
          dnnsf.updateQueryStringParam(&#39;graf10Agregare&#39;,&#39;zile&#39;);
          dnnsf.updateQueryStringParam(&#39;graf10Start&#39;, firstFormatted);
          dnnsf.updateQueryStringParam(&#39;graf10End&#39;, lastFormatted);

          dnnsf.api.actionForm.initForm(619);
        }
      },

      plugins: {
        legend: {
          display: hasData
        },
        tooltip: {
          enabled: hasData
        }
      },

      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0
          },
          title: {
            display: true,
            text: &#39;Număr accesări&#39;
          }
        },
        x: {
          title: {
            display: true,
            text: agregare === &#39;zile&#39; ? &#39;Zi&#39; : &#39;Lună&#39;
          }
        }
      }
    }
  });
&lt;/script&gt;]]&gt;&lt;/Value&gt;
